#include <stdio.h>

/* 带参数的宏：在预处理阶段做文本替换。
   每个参数和整个表达式都套了一层括号，嵌套使用时才不会算错 */
#define MAX(a, b) ((a) > (b) ? (a) : (b))

int main() {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);

    /* 宏可以嵌套：内层先取前两个数里的大者，外层再和第三个数比 */
    printf("%d\n", MAX(MAX(a, b), c));
    return 0;
}

#include <stdio.h>

/* 调试开关：把下面这一行注释掉再重新编译，调试输出就整段消失了 */
#define DEBUG

int main() {
    int n;
    scanf("%d", &n);

#ifdef DEBUG
    /* 只有 DEBUG 被定义时，这一行才会参与编译 */
    printf("debug: n=%d\n", n);
#endif

    /* 正常的输出，不管有没有定义 DEBUG 都有 */
    printf("%d\n", n * n);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    scanf("%d", &n);

    /* n 可能为 0，此时不去申请、更不解引用，避免访问无效内存 */
    int *a = NULL;
    if (n > 0) {
        a = (int *)malloc(n * sizeof(int));
        /* malloc 失败会返回 NULL，直接用它程序会崩溃 */
        if (a == NULL) {
            return 1;
        }
    }

    int sum = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        sum += a[i];
    }

    printf("%d\n", sum);

    /* 借来的内存必须还：free(NULL) 是安全的，所以这里不需要额外判断 */
    free(a);
    return 0;
}

