#include <stdio.h>
#include <stdlib.h>

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    /* 第一层：n 个 int* 组成的「指针数组」，每个元素将来指向一行 */
    int **grid = (int **)malloc(n * sizeof(int *));
    if (grid == NULL) {
        return 1;
    }

    /* 第二层：每一行单独申请 m 个 int */
    for (int i = 0; i < n; i++) {
        grid[i] = (int *)malloc(m * sizeof(int));
        if (grid[i] == NULL) {
            return 1;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            scanf("%d", &grid[i][j]);
        }
    }

    /* grid[i][j] 和 *(*(grid + i) + j) 完全等价，用起来就像普通二维数组 */
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = 0; j < m; j++) {
            sum += grid[i][j];
        }
        printf("%d\n", sum);
    }

    /* 释放顺序必须和申请顺序相反：先还每一行，最后还指针数组本身 */
    for (int i = 0; i < n; i++) {
        free(grid[i]);
    }
    free(grid);
    return 0;
}

