#include <stdio.h>

int op_add(int a, int b) { return a + b; }
int op_sub(int a, int b) { return a - b; }
int op_mul(int a, int b) { return a * b; }

/* 除数不会为 0：调用它之前已经检查过了 */
int op_div(int a, int b) { return a / b; }

int main() {
    int a, b;
    char op;

    /* 格式串里 %c 前面那个空格很重要：它让 scanf 先跳过空白再读运算符 */
    if (scanf("%d %c %d", &a, &op, &b) != 3) {
        return 1;
    }

    /* 函数指针：*(fn) 外面的括号不能省，它表示 fn 是指针，而不是返回 int* 的函数 */
    int (*fn)(int, int) = NULL;

    switch (op) {
        case '+': fn = op_add; break;
        case '-': fn = op_sub; break;
        case '*': fn = op_mul; break;
        case '/': fn = op_div; break;
        default:  fn = NULL;   break;
    }

    if (fn == NULL) {
        printf("error\n");
    } else if (op == '/' && b == 0) {
        /* 整数除以 0 是未定义行为，可能直接崩溃，必须在调用前拦下来 */
        printf("error\n");
    } else {
        printf("%d\n", fn(a, b));   /* 写 (*fn)(a, b) 完全等价 */
    }

    return 0;
}

