#include <stdio.h>

/* static 局部变量只初始化一次，函数返回后它依然活着，
   所以下一次调用看到的是上次留下的值 */
int add_to_total(int x) {
    static int total = 0;
    total += x;
    return total;
}

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        printf("%d\n", add_to_total(x));
    }

    return 0;
}

